function divide(a, b) {
  if (b === 0) {
    throw new Error("DivisionByZeroError: Divisor cannot be 0.");
  }
  return a / b;
}

try {
  console.log(divide(10, 0));
} catch (err) {
  console.log("Caught:", err.message);
}

