const fs = require('fs');

function main() {
    const s = fs.readFileSync(0, 'utf-8').trim();
    if (s.length > 0) {
        let val;
        if (s.startsWith('0x') || s.startsWith('0X')) {
            val = parseInt(s, 16);
        } else if (s.startsWith('0') && s.length > 1) {
            val = parseInt(s, 8);
        } else {
            val = parseInt(s, 10);
        }
        console.log(val);
    }
}

main();

